import { cpSync, createReadStream, existsSync, statSync } from 'node:fs'
import path from 'node:path'
import tailwindcss from '@tailwindcss/vite'
import react from '@vitejs/plugin-react'
import { defineConfig, type Plugin } from 'vite'

const repoRoot = path.resolve(import.meta.dirname, '../..')

/**
 * Serves repo-level static folders next to the app:
 *   /data/*  -> data/public/*   (the data contract; generated by `pnpm data`)
 *   /media/* -> media/*         (Describe-popup videos)
 *   /basemap/* -> basemap/*     (NASA GIBS Blue Marble tiles, levels 0-5, for offline use; `pnpm basemap`)
 * In dev they are served from disk; in build they are copied into dist/.
 */
function repoStatic(): Plugin {
  const mounts = [
    { url: '/data/', dir: path.join(repoRoot, 'data', 'public') },
    { url: '/media/', dir: path.join(repoRoot, 'media') },
    { url: '/basemap/', dir: path.join(repoRoot, 'basemap') },
  ]
  const types: Record<string, string> = {
    '.json': 'application/json',
    '.png': 'image/png',
    '.webm': 'video/webm',
    '.mp4': 'video/mp4',
    '.jpeg': 'image/jpeg',
  }
  let outDir = 'dist'
  return {
    name: 'repo-static',
    configResolved(config) {
      outDir = path.resolve(config.root, config.build.outDir)
    },
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        const url = decodeURIComponent((req.url ?? '').split('?')[0])
        const mount = mounts.find((m) => url.startsWith(m.url))
        if (!mount) return next()
        const file = path.resolve(mount.dir, url.slice(mount.url.length))
        if (!file.startsWith(mount.dir + path.sep) || !existsSync(file) || !statSync(file).isFile()) {
          res.statusCode = 404
          return res.end()
        }
        res.setHeader('Content-Type', types[path.extname(file)] ?? 'application/octet-stream')
        createReadStream(file).pipe(res)
      })
    },
    closeBundle() {
      for (const m of mounts) {
        if (existsSync(m.dir)) cpSync(m.dir, path.join(outDir, m.url), { recursive: true })
      }
    },
  }
}

// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), tailwindcss(), repoStatic()],
  resolve: {
    alias: { '@': path.resolve(import.meta.dirname, './src') },
  },
  // Cesium loads its workers and assets from here (see scripts/copy-cesium.mjs).
  define: {
    CESIUM_BASE_URL: JSON.stringify('/cesium/'),
  },
  // Sharing through VS Code port forwarding (dev tunnels) or GitHub Codespaces: allow those host names.
  // Share the production preview (pnpm start, port 4173), not the dev server: in dev mode the assistant's key
  // from apps/web/.env.local is part of the served code.
  server: { allowedHosts: ['.devtunnels.ms', '.app.github.dev'] },
  preview: { allowedHosts: ['.devtunnels.ms', '.app.github.dev'] },
})
